    'use argui::{\n    runtime::{Context, Render},\n    text::TextStyle,\n    ui::{Element, EventType, Sides, UiEventKind, percent},\n    widgets::{Button, default_theme},\n};\n\n#[derive(Default)]\npub struct Example {\n    completed: usize,\n}\n\nimpl Render for Example {\n    fn render(&mut self, cx: &mut Context<Self>) -> Element {\n        let themes = default_theme(cx.environment());\n        let theme = themes.resolve(cx.environment().color_scheme);\n        let checks = [\n            "State is explicit",\n            "Views stay pure",\n            "Effects have owners",\n        ];\n        let rows = checks.into_iter().enumerate().map(|(index, label)| {\n            let mark = if index < self.completed { "✓" } else { "○" };\n            Element::text(format!("{mark}  {label}")).text_style(TextStyle {\n                color: theme.foreground,\n                ..TextStyle::default()\n            })\n        });\n        Element::column(\n            rows.chain([Button::new("next", "Complete next", theme.button())\n                .enabled(self.completed < checks.len())\n                .build()]),\n        )\n        .width(percent(1.0))\n        .height(percent(1.0))\n        .padding(Sides::length(28.0))\n        .gap(14.0)\n        .background(theme.background)\n        .on(cx.listener(EventType::Click, |app, event, cx| {\n            if event.target_key() == Some("next") && matches!(event.kind, UiEventKind::Click(_)) {\n                app.completed = (app.completed + 1).min(3);\n                cx.notify();\n            }\n        }))\n    }\n}\n',
